import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { positionLocal, vec3, mix, uniform, uv, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, DirectionalLight, PointLight } = ctx.THREE;

  const COLORS = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10', surface: '#101017', ink: '#16161d',
    paper: '#e8ecf2', accent: '#ff2a38',
  };

  const group = new Group();
  group.userData.handlers = {};
  const timelines = [];
  const primHandles = [];
  const disposables = [];

  // ---- Backdrop stage plane with vertical engineered gradient ----
  const backdropGeo = new PlaneGeometry(7, 5.5);
  const backdropMat = new MeshBasicNodeMaterial();
  const cTop = uniform(vec3(...new Color('#13131a').toArray()));
  const cBot = uniform(vec3(...new Color('#0b0b10').toArray()));
  const vy = uv().y;
  backdropMat.colorNode = mix(cBot, cTop, vy);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -1.5);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---- Lights (node-local rim + key) ----
  const key = new DirectionalLight(new Color(COLORS.paper), 1.1);
  key.position.set(2.5, 3, 4);
  group.add(key);

  const rim = new PointLight(new Color(COLORS.accent), 1.2, 20);
  rim.position.set(-3, -1, 2.5);
  group.add(rim);

  // ---- Text content bridging ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const findRole = (r) => items.find((i) => i.role === r);
  const captionItem = findRole('caption');
  const heroItem = findRole('hero');
  const subheadItem = findRole('subhead');

  const captionText = (captionItem?.text ?? 'NOVA ATELIER / CALIBRE PROGRAM').toUpperCase();
  const heroText = heroItem?.text ?? 'TIME, MACHINED.';
  const subheadText = subheadItem?.text ?? 'Every calibre begins as a solid billet.';

  // ---- Caption kicker (mono 700 uppercase) ----
  const caption = ctx.fontAtlas.createText(captionText, {
    fontSize: 30,
    color: COLORS.paper,
    align: 'center',
    letterSpacingPx: 6,
  });
  caption.position.set(0, 1.15, 0);
  group.add(caption);

  // ---- Hero headline as per-word depth-offset planes ----
  const heroGroup = new Group();
  heroGroup.position.set(0, 0.4, 0);
  group.add(heroGroup);

  const words = heroText.split(' ');
  const zOffsets = [0.12, 0.0, -0.12];
  const heroWordObjs = [];
  const totalChars = heroText.length;
  // approximate layout width
  const wordSpacing = 0.14;
  let cursor = 0;
  // First measure total to center
  const approxCharW = 0.42;
  const totalW = totalChars * approxCharW + (words.length - 1) * wordSpacing;
  let x = -totalW / 2;

  words.forEach((word, wi) => {
    const wObj = ctx.fontAtlas.createText(word, {
      fontSize: 200,
      color: COLORS.paper,
      align: 'left',
    });
    const wWidth = word.length * approxCharW;
    wObj.position.set(x, 0, zOffsets[wi % zOffsets.length]);
    wObj.scale.setScalar(0.62 / 0.62); // em-height driven by fontSize; keep 1
    x += wWidth + wordSpacing;
    heroGroup.add(wObj);
    heroWordObjs.push(wObj);
  });

  // ---- Accent underline rule ----
  const ulGeo = new PlaneGeometry(2.6, 0.045);
  const ulMat = new MeshStandardNodeMaterial();
  ulMat.color = new Color(COLORS.accent);
  ulMat.emissive = new Color(COLORS.accent);
  ulMat.emissiveIntensity = 1.2;
  ulMat.roughness = 0.5;
  ulMat.metalness = 0.2;
  const underline = new Mesh(ulGeo, ulMat);
  // anchor left: shift geometry origin
  ulGeo.translate(1.3, 0, 0);
  underline.position.set(-1.3, -0.05, 0.1);
  underline.scale.x = 0;
  group.add(underline);
  disposables.push(ulGeo, ulMat);

  // ---- Subhead ----
  const subhead = ctx.fontAtlas.createText(subheadText, {
    fontSize: 64,
    color: COLORS.paper,
    align: 'center',
  });
  subhead.position.set(0, -0.65, 0);
  group.add(subhead);

  // ---- Motion: kinetic entrance ----
  const bezRise = 'power3.out';
  const bezSettle = 'power4.out';

  // caption fade
  caption.position.y = 1.15 + 0.2;
  const capTl = gsap.timeline();
  capTl.to(caption.position, { y: 1.15, duration: 0.5, ease: 'power2.out' }, 0);
  timelines.push(capTl);

  // per-word rise stagger
  const stagger = ((config.cinematicPrimitives?.find((p) => p.name === 'kinetic-text')?.params?.staggerMs) ?? 60) / 1000;
  const rise = (config.cinematicPrimitives?.find((p) => p.name === 'kinetic-text')?.params?.riseUnits) ?? 0.35;

  const heroTl = gsap.timeline();
  heroWordObjs.forEach((w, i) => {
    const baseY = w.position.y;
    w.position.y = baseY + rise;
    heroTl.to(w.position, { y: baseY, duration: 0.7, ease: bezRise }, i * stagger * 3);
  });

  const lastLand = (heroWordObjs.length - 1) * stagger * 3 + 0.7;

  // group weighted-settle
  heroGroup.scale.setScalar(1.04);
  heroTl.to(heroGroup.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: bezSettle }, lastLand);

  // underline scaleX
  heroTl.to(underline.scale, { x: 1, duration: 0.5, ease: 'power2.out' }, lastLand + 0.12);

  // subhead fade up
  subhead.position.y = -0.65 - 0.2;
  heroTl.to(subhead.position, { y: -0.65, duration: 0.5, ease: 'power2.out' }, lastLand + 0.2);

  timelines.push(heroTl);

  // ---- Apply cinematic primitives ----
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const fn = ctx.primitives?.[p.name];
    if (fn) {
      const handle = fn(heroGroup, p.params ?? {});
      if (handle) primHandles.push(handle);
    }
  }

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const h of primHandles) h?.cleanup?.();
    for (const d of disposables) d?.dispose?.();
    group.traverse((o) => {
      if (o.geometry) o.geometry.dispose?.();
      if (o.material) {
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose?.());
        else o.material.dispose?.();
      }
    });
  };

  return group;
}
